from typing import List


class Solution:
    def sum_of_digits(self, number):
        digit_sum = 0
        while number > 0:
            digit_sum += number % 10
            number = number // 10
        return digit_sum

    def maximumSum(self, nums: List[int]):
        n = len(nums)
        sum_no_mapping = dict()
        for i in range(n):
            digit_sum = self.sum_of_digits(nums[i])
            if digit_sum in sum_no_mapping:
                if len(sum_no_mapping[digit_sum]) == 1:
                    sum_no_mapping[digit_sum].append(nums[i])
                elif len(sum_no_mapping[digit_sum]) == 2:
                    first_no = max(sum_no_mapping[digit_sum][0], sum_no_mapping[digit_sum][1])
                    second_no = max(min(sum_no_mapping[digit_sum][0], sum_no_mapping[digit_sum][1]), nums[i])
                    sum_no_mapping[digit_sum] = [first_no, second_no]
            else:
                sum_no_mapping[digit_sum] = [nums[i]]

        maximum_sum_of_digits = -1
        for numbers in sum_no_mapping.values():
            if len(numbers) == 1:
                continue
            else:
                maximum_sum_of_digits = max(maximum_sum_of_digits, sum(numbers))
        return maximum_sum_of_digits



